-- Daily dashboard insights: the few lines at the top of the dashboard saying what changed and what
-- to do about it (modules/ai/insights).
--
-- One row per website per UTC day. Generated by a scheduled job, never on a page load, and stored so
-- the dashboard reads it for free. `lines` is what the owner sees; `signals` is what the code found
-- and the lines were worded from, kept so a line can be traced back to the numbers behind it.
--
-- The table holds counts and plain-language lines, never visitor data. Tokens and cost are recorded
-- per row so what insights cost can be read straight from the table.
--
-- Deleted with its website, and by the AI retention sweep once old.

CREATE TABLE IF NOT EXISTS ai_insights (
  website_id UUID NOT NULL REFERENCES websites(id) ON DELETE CASCADE,
  insight_date DATE NOT NULL,
  -- ready | insufficient_data | failed
  status VARCHAR(20) NOT NULL,
  -- ai: worded by the model. rules: worded from templates (no model, or its output failed the checks).
  source VARCHAR(8) NOT NULL DEFAULT 'rules',
  lines JSONB NOT NULL DEFAULT '[]'::jsonb,
  signals JSONB NOT NULL DEFAULT '[]'::jsonb,
  reason TEXT,
  model VARCHAR(100),
  input_tokens INTEGER NOT NULL DEFAULT 0,
  output_tokens INTEGER NOT NULL DEFAULT 0,
  cost_usd NUMERIC(12, 6) NOT NULL DEFAULT 0,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  PRIMARY KEY (website_id, insight_date)
);

CREATE INDEX IF NOT EXISTS ix_ai_insights_created ON ai_insights (created_at);
